parameters:
{
  "signature": {
    "baseline_config": {
      "schema_version": "t09-persistence-v1",
      "max_history_age_hours": 24,
      "age_limit_inclusive": true,
      "train_statistic": "median",
      "train_statistic_scope": "T05_operational_train_origins",
      "smoke_rows_per_station": 168,
      "headline_cohort": "primary",
      "residual_definition": "y_pred_minus_y_true",
      "budget": {
        "smoke_before_full": true,
        "max_full_runs": 1
      },
      "note": "Age limit fixed before validation metrics; no tuning or prediction clipping. Smoke is execution evidence only."
    },
    "split_manifest_sha256": "6d3ac3f05da50324a65c34c1e1601b5df45fefc3d2e6d0e834d43a27062d0e42",
    "anchor_sha256": "b9646da98017bc0b02f622ee928df0b70185e8a6312a2a9512329d4d04057e7f",
    "source_sha256": {
      "baseline.py": "ea0787f928f1893a7429f0ecb84de2d630215d1facb668ebda64b9b2754e1572",
      "evaluation.py": "903dad88d32507360c18e67d7c0559bea069a94e6859978244c442196d5ec27a",
      "metrics.py": "c282e54515b5ad25fa9b67c576c8d082da9833878d65ac89e22ac7714b221769",
      "run_baseline.py": "75fa263fa30e9499c367e3263ce2c52de0342f64f9e96e99208390f81e6681a9"
    },
    "prediction_policy": {
      "negative_predictions": "identity",
      "applies_to": [
        "persistence",
        "ridge",
        "random_forest"
      ]
    },
    "fallback_order": [
      "last_observed_same_station",
      "training_station_median",
      "training_global_median",
      "unavailable"
    ]
  },
  "project_config": {
    "seed": 42,
    "horizon_hours": 1,
    "mode": "smoke",
    "available_modes": [
      "smoke",
      "full"
    ],
    "problem": {
      "task_type": "regression",
      "target_column": "PM2.5",
      "target_unit": "ug/m3",
      "group_column": "station",
      "input_time_column": "input_timestamp",
      "target_time_column": "target_timestamp",
      "station_scope": "observed_stations",
      "current_observation_available": true,
      "forecast_strategy": "rolling_one_hour"
    },
    "split": {
      "timestamp_column": "target_timestamp",
      "validation_start": "2015-03-01T00:00:00",
      "test_start": "2016-03-01T00:00:00",
      "timestamp_convention": "source_local_naive",
      "test_locked": true,
      "final_refit_train_validation": true
    },
    "sample_construction": {
      "target_value_column": "target_pm25",
      "sample_id_scheme": "pm25-h1-v1",
      "target_missing_policy": "drop",
      "origin_missing_policy": "retain_operational_flag_primary",
      "holdout_label_rule": "at_or_before_first_origin"
    },
    "temporal_cv": {
      "strategy": "expanding_window",
      "partition": "train",
      "group_by": "unique_target_timestamp",
      "fit_target_must_precede_first_origin": true,
      "folds": [
        {
          "fold_id": 1,
          "evaluation_start": "2014-06-01T00:00:00",
          "evaluation_end": "2014-09-01T00:00:00"
        },
        {
          "fold_id": 2,
          "evaluation_start": "2014-09-01T00:00:00",
          "evaluation_end": "2014-12-01T00:00:00"
        },
        {
          "fold_id": 3,
          "evaluation_start": "2014-12-01T00:00:00",
          "evaluation_end": "2015-03-01T00:00:00"
        }
      ]
    },
    "features": {
      "A": {
        "legacy_name": "F0",
        "measurements": [
          "PM2.5",
          "PM10",
          "SO2",
          "NO2",
          "CO",
          "O3",
          "TEMP",
          "PRES",
          "DEWP",
          "RAIN",
          "WSPM"
        ],
        "categorical": [
          "station",
          "wd"
        ],
        "calendar_reference": "target_timestamp",
        "calendar": [
          "target_hour",
          "target_month",
          "target_day_of_week"
        ],
        "cyclic_calendar": {
          "target_hour": 24,
          "target_month": 12
        }
      },
      "B": {
        "legacy_name": "F1",
        "extends": "A",
        "pm25_lag_hours": [
          1,
          3,
          6,
          12,
          24
        ],
        "pm25_rolling_windows_hours": [
          3,
          6,
          12,
          24
        ],
        "rolling_stats": [
          "mean",
          "std"
        ],
        "rolling_std_ddof": 1,
        "rolling_include_current": true,
        "rolling_min_periods": "window"
      },
      "C": {
        "extends": "B",
        "selector_fit_scope": "training_partition_of_each_run_or_fold",
        "selection_method": null,
        "selected_features": null
      }
    },
    "evaluation": {
      "baseline": "persistence",
      "models": [
        "ridge",
        "random_forest"
      ],
      "initial_parameters": {
        "ridge": {
          "alpha": 1.0
        },
        "random_forest": {
          "n_estimators": 300,
          "max_depth": null,
          "min_samples_leaf": 1,
          "max_features": 1.0,
          "random_state": 42,
          "n_jobs": 1
        }
      },
      "primary_metric": "MAE",
      "secondary_metrics": [
        "RMSE",
        "R2"
      ],
      "same_sample_ids": true,
      "baseline_fallback_order": [
        "last_observed_same_station",
        "training_station_median",
        "training_global_median",
        "unavailable"
      ]
    },
    "experiment_logging": {
      "infrastructure_task_id": "T04-LOG",
      "index": "experiments/experiment_log.csv",
      "runs": "artifacts/experiments"
    },
    "paths": {
      "raw_data": "data/raw",
      "processed_data": "data/processed",
      "artifacts": "artifacts",
      "figures": "reports/figures"
    }
  },
  "configured_seed": 42,
  "randomness_used": false
}

preprocessing:
{
  "applied": false,
  "fallback_statistics": "train-origin medians only",
  "config": {
    "schema_version": "t08-preprocessing-v1",
    "numeric": {
      "imputation_strategy": "median",
      "keep_empty_features": true,
      "missing_indicators": "all",
      "scale": {
        "ridge": true,
        "random_forest": false
      }
    },
    "categorical": {
      "imputation_strategy": "constant",
      "fill_value": "__MISSING__",
      "handle_unknown": "ignore",
      "sparse_output": false
    },
    "output": {
      "format": "pandas",
      "verbose_feature_names": true
    },
    "prediction_postprocessing": {
      "negative_predictions": "identity",
      "applies_to": [
        "persistence",
        "ridge",
        "random_forest"
      ]
    }
  }
}

